import { z } from "zod";
const zProgressBarProps = z.object({
    label: z.string().optional(),
    value: z.number(),
    max: z.number().default(100),
});
export function ProgressBar(define) {
    return define("ProgressBar")
        .props(zProgressBarProps)
        .render((props) => ({
        id: props.id,
        label: props.label,
        value: props.value,
        max: props.max,
    }));
}
